/**
 * Test implementation of PathNormalizationAdapter for unit tests
 * Provides predictable repository information for testing
 */

import type { PathNormalizationAdapter, SystemInfo } from './PathNormalizationAdapter';
import type { RepositoryInfo } from '../types/PathNormalization';

/**
 * Test adapter with predefined repositories for testing
 */
export class TestPathNormalizationAdapter implements PathNormalizationAdapter {
  private repositories: Map<string, RepositoryInfo>;

  constructor(repositories?: Map<string, RepositoryInfo>) {
    // Default test repositories
    this.repositories = repositories || new Map([
      ['/Users/test/project', {
        root: '/Users/test/project',
        remoteUrl: 'https://github.com/test/project.git',
        owner: 'test',
        repo: 'project',
        branch: 'main'
      }],
      ['/Users/test/project1', {
        root: '/Users/test/project1',
        remoteUrl: 'https://github.com/test/project1.git',
        owner: 'test',
        repo: 'project1',
        branch: 'main'
      }],
      ['/Users/test/project2', {
        root: '/Users/test/project2',
        remoteUrl: 'https://github.com/test/project2.git',
        owner: 'test',
        repo: 'project2',
        branch: 'feature/test'
      }]
    ]);
  }

  async getRawRepositoryInfo(absolutePath: string): Promise<RepositoryInfo | null> {
    // Find the most specific (longest) matching repository
    let bestMatch: RepositoryInfo | null = null;
    let bestMatchLength = 0;

    for (const [root, info] of this.repositories) {
      if (absolutePath.startsWith(root) && root.length > bestMatchLength) {
        // Check that it's a proper path boundary (not matching partial directory names)
        if (absolutePath.length === root.length || absolutePath[root.length] === '/') {
          bestMatch = info;
          bestMatchLength = root.length;
        }
      }
    }

    return bestMatch;
  }

  getSystemInfo(): SystemInfo {
    return {
      homeDir: '/Users/test',
      pathSeparator: '/',
      platform: 'darwin'
    };
  }

  resolvePath(relativePath: string, workingDirectory: string): string {
    if (this.isAbsolutePath(relativePath)) {
      return relativePath;
    }
    // Handle ./ prefix
    if (relativePath.startsWith('./')) {
      relativePath = relativePath.slice(2);
    }
    return `${workingDirectory}/${relativePath}`.replace(/\/+/g, '/');
  }

  isAbsolutePath(path: string): boolean {
    return path.startsWith('/') || /^[A-Za-z]:[\\/]/.test(path);
  }

  getRelativePath(fromPath: string, toPath: string): string {
    if (!toPath.startsWith(fromPath)) {
      return toPath;
    }
    // Remove the fromPath and any leading slash
    const relative = toPath.slice(fromPath.length);
    return relative.replace(/^\//, '') || '.';
  }

  isAvailable(): boolean {
    return true;
  }
}

/**
 * Minimal adapter that simulates no repositories found
 */
export class NoRepositoryAdapter implements PathNormalizationAdapter {
  async getRawRepositoryInfo(): Promise<RepositoryInfo | null> {
    return null;
  }

  getSystemInfo(): SystemInfo {
    return {
      homeDir: '/',
      pathSeparator: '/',
      platform: 'linux'
    };
  }

  resolvePath(relativePath: string, workingDirectory: string): string {
    return relativePath.startsWith('/') ? relativePath : `${workingDirectory}/${relativePath}`;
  }

  isAbsolutePath(path: string): boolean {
    return path.startsWith('/');
  }

  getRelativePath(_fromPath: string, toPath: string): string {
    return toPath;
  }

  isAvailable(): boolean {
    return true;
  }
}

/**
 * Factory function to create custom test adapters with specific repositories
 */
export function createTestAdapter(repositories: Array<[string, RepositoryInfo]>): TestPathNormalizationAdapter {
  return new TestPathNormalizationAdapter(new Map(repositories));
}